from itertools import combinations
G=['.##.##.','######.','.##.#..','..###..','.......','.......','.......']
cells={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x=='#'}
placements=[]
for r in range(6):
 for c in range(6):
  block={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if block<=cells: placements.append(('S',block))
  for missing in block:
   shape=block-{missing}
   if shape<=cells: placements.append(('L'+str(missing),shape))
sol=[]
def rec(remaining, used, square_count):
 if not remaining:
  if square_count==1 and len(used)==5: sol.append(used[:])
  return
 if len(used)>=5:return
 x=min(remaining)
 for kind,shape in placements:
  if x in shape and shape<=remaining and not (kind=='S' and square_count):
   rec(remaining-shape, used+[(kind,shape)], square_count+(kind=='S'))
rec(cells,[],0)
print('cells',len(cells),'solutions',len(sol))
for i,s in enumerate(sol[:20]):
 print('solution',i)
 for k,sh in s:
  print(k,sorted(sh))
